import React, { useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { EditorContent, useEditor } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import LinkExtension from '@tiptap/extension-link';
import Image from '@tiptap/extension-image';
import Youtube from '@tiptap/extension-youtube';
import { blogApi, Post, PostInput, Category, Status } from '../../blog/api';
import '../../blog/blog.css';
const emptyDoc = {type:'doc',content:[{type:'paragraph'}]};
const blank:PostInput={title:'',slug:'',excerpt:'',content:emptyDoc,category:'industry-insights',featured_image:'',seo_title:'',seo_description:'',status:'draft'};
function makeSlug(s:string){return s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,180)}
export default function BlogEditor(){
 const {id}=useParams();const navigate=useNavigate();const [form,setForm]=useState<PostInput>(blank);const [loading,setLoading]=useState(!!id);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [slugEdited,setSlugEdited]=useState(false);
 const editor=useEditor({extensions:[StarterKit,LinkExtension.configure({openOnClick:false}),Image,Youtube],content:emptyDoc});
 useEffect(()=>{if(!id)return;let live=true;blogApi.adminPosts().then(posts=>{const post=posts.find((p:Post)=>p.id===id);if(!post)throw new Error('Article not found');if(live){setForm({title:post.title,slug:post.slug,excerpt:post.excerpt||'',content:post.content,category:post.category,featured_image:post.featured_image||'',seo_title:post.seo_title||'',seo_description:post.seo_description||'',status:post.status});editor?.commands.setContent(post.content);setSlugEdited(true)}}).catch(e=>{if(live)setError(e.message)}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[id,editor]);
 function field<K extends keyof PostInput>(key:K,value:PostInput[K]){setForm(prev=>({...prev,[key]:value}))}
 async function uploadImage(featured=false){const picker=document.createElement('input');picker.type='file';picker.accept='image/jpeg,image/png,image/webp,image/gif';picker.onchange=async()=>{const file=picker.files?.[0];if(!file)return;setBusy(true);setError('');try{const result=await blogApi.image(file);if(featured)field('featured_image',result.url);else editor?.chain().focus().setImage({src:result.url,alt:file.name}).run()}catch(e:any){setError(e.message)}finally{setBusy(false)}};picker.click()}
 function addLink(){if(!editor)return;const href=window.prompt('Enter link URL (https://...)');if(!href)return;try{const u=new URL(href);if(!['http:','https:'].includes(u.protocol))throw Error();editor.chain().focus().extendMarkRange('link').setLink({href:u.toString()}).run()}catch{setError('Please enter a valid https:// URL')}}
 function addVideo(){if(!editor)return;const url=window.prompt('Paste a YouTube video URL');if(url)editor.commands.setYoutubeVideo({src:url})}
 async function save(status:Status){if(!editor)return;setBusy(true);setError('');try{const input={...form,status,content:editor.getJSON()};if(!input.title.trim()||!input.slug.trim())throw new Error('Title and slug are required');if(id)await blogApi.update(id,input);else await blogApi.create(input);navigate('/admin/blog')}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 return <main className="btr-blog-admin"><div className="btr-blog-admin-wide"><div className="btr-blog-admin-head"><div><Link to="/admin/blog">← Dashboard</Link><h1>{id?'Edit article':'New article'}</h1></div><div><button disabled={busy||loading} className="btr-blog-secondary" onClick={()=>save('draft')}>Save draft</button> <button disabled={busy||loading} onClick={()=>save('published')}>Publish</button></div></div>
 {error&&<p role="alert" className="btr-blog-error">{error}</p>}{loading?<p>Loading...</p>:<div className="btr-blog-editor-grid"><div className="btr-blog-admin-box"><label>Title<input value={form.title} maxLength={200} onChange={e=>{field('title',e.target.value);if(!slugEdited)field('slug',makeSlug(e.target.value))}}/></label><label>URL slug<input value={form.slug} maxLength={180} onChange={e=>{setSlugEdited(true);field('slug',makeSlug(e.target.value))}}/></label><label>Excerpt<textarea rows={3} value={form.excerpt||''} onChange={e=>field('excerpt',e.target.value)}/></label>
 <label>Article body</label><div className="btr-blog-toolbar"><button type="button" onClick={()=>editor?.chain().focus().toggleBold().run()}>Bold</button><button type="button" onClick={()=>editor?.chain().focus().toggleItalic().run()}>Italic</button><button type="button" onClick={()=>editor?.chain().focus().toggleHeading({level:2}).run()}>H2</button><button type="button" onClick={()=>editor?.chain().focus().toggleHeading({level:3}).run()}>H3</button><button type="button" onClick={()=>editor?.chain().focus().toggleBulletList().run()}>Bullets</button><button type="button" onClick={()=>editor?.chain().focus().toggleOrderedList().run()}>Numbers</button><button type="button" onClick={addLink}>Link</button><button type="button" onClick={()=>uploadImage()}>Image</button><button type="button" onClick={addVideo}>YouTube</button></div><div className="btr-blog-editable"><EditorContent editor={editor}/></div></div>
 <aside className="btr-blog-admin-box"><label>Category<select value={form.category} onChange={e=>field('category',e.target.value as Category)}><option value="industry-insights">Industry Insights</option><option value="building-btr">Building BTR</option></select></label><label>Featured image</label>{form.featured_image&&<img className="btr-blog-feature-preview" src={form.featured_image} alt="Featured preview"/>}<button className="btr-blog-secondary" type="button" onClick={()=>uploadImage(true)}>Upload featured image</button><label>SEO title<input value={form.seo_title||''} onChange={e=>field('seo_title',e.target.value)}/></label><label>SEO description<textarea rows={4} value={form.seo_description||''} onChange={e=>field('seo_description',e.target.value)}/></label><p>Status when saved: <strong>{form.status}</strong></p></aside></div>}</div></main>
}
